30	// A-16 (DEVDESK-143), the cross-cutting guard, started with the :jobs pilot
31	// (DEVDESK-142).
32	//
33	// The guard answers one question for every view the router can build: is it on
34	// the activity column, is it waiting for its migration, or is it exempt for a
35	// stated reason? A view that is none of the three fails the test by name. For a
36	// migrated view it also checks the column, the help legend, the retired
37	// mechanisms in its declared sources (including its own ticks), and the footer
38	// of its selected row. Declared exceptions may only shrink, and follow their
39	// stories: pendingTables here, declaredRowChains in animation_guard_test.go.
40	
41	// activityView is what a migrated view exposes to the guard: read-only tables,
42	// keyed "<view>/<table>".
43	type activityView interface {
44		ActivityTables() map[string]datatable.ActivityTable
45	}
46	
47	// migratedTables are the tables already on the activity column, by view.
48	var migratedTables = map[command.ViewType][]string{
49		command.ViewJobs:         {"jobs/runs", "jobs/targets"},
50		command.ViewWorkspaces:   {"ws"},
51		command.ViewSecurity:     {"sec/inventory"},
52		command.ViewOCIResources: {"oci/images", "oci/networks", "oci/volumes", "oci/registries", "oci/registry-browser"},
53		command.ViewGitExplorer:  {"explorer/tree", "explorer/clone-list"},
54		command.ViewTemplates:    {"templates"},
55		command.ViewNetdiag:      {"netdiag/ports"},
56		command.ViewAgentUsage:   {"agent-usage/agents"},
57		command.ViewContainers:   {"containers"},
58	}
59	
60	// pendingTable is a table that still has to move to the activity column.
61	type pendingTable struct {
62		Table string
63		View  command.ViewType
64		Story string
65	}
66	
67	// pendingTables may only shrink: each migration story removes its own entries.
68	var pendingTables = []pendingTable{}
69	
70	// maxPendingTables is the ceiling: adding an exception means raising both the
71	// list and this constant in the same diff, which is visible in review. Lower it
72	// with every migration.
73	const maxPendingTables = 0
74	
75	// exemptViews have no long-running operation to show per row (inventory:
76	// "sans objet" or out of the batch), each with its reason.
77	var exemptViews = map[command.ViewType]string{
78		command.ViewDashboard:     "no table with row operations; the dashboard is a summary",
79		command.ViewStatus:        "monitors are polled as a whole, not per-row operations",
80		command.ViewGitAuth:       "a form, no table",
81		command.ViewConfiguration: "a form of settings, no table of operations",
82		command.ViewAbout:         "static facts, no table",
83		command.ViewFiles:         "out of the batch, candidate for a later S story (the delete goes through the registry, no story covers it)",
84		command.ViewViewer:        "a document pane, no table",
85	}
86	
87	func pendingViews() map[command.ViewType][]pendingTable {
88		out := map[command.ViewType][]pendingTable{}
89		for _, p := range pendingTables {
90			out[p.View] = append(out[p.View], p)
91		}
92		return out
93	}
94	
95	func TestActivityGuardPendingListOnlyShrinks(t *testing.T) {
96		if got := len(pendingTables); got > maxPendingTables {
97			t.Errorf("pendingTables has %d entries, ceiling is %d: the list may only shrink (A-16 criterion 6)", got, maxPendingTables)
98		}
99		seen := map[string]bool{}
100		for _, p := range pendingTables {
101			if p.Story == "" {
102				t.Errorf("pending table %q names no story", p.Table)
103			}
104			if seen[p.Table] {
105				t.Errorf("pending table %q is listed twice", p.Table)
106			}
107			seen[p.Table] = true
108		}
109	}
