111	// builtView returns the view the router builds for vt, laid out at 60x30.
112	func builtView(t *testing.T, vt command.ViewType) tea.Model {
113		t.Helper()
114		a := routerAt(t, &bareView{}, 60, 30) // isolateHome, session-only secrets
115		a.createView(vt)
116		m := a.views[vt]
117		if m == nil {
118			t.Fatalf("view %q: the router did not build it", vt)
119		}
120		m, _ = m.Update(tea.WindowSizeMsg{Width: 60, Height: 30})
121		return m
122	}
