164	// Criterion 6: every view the router builds is migrated, pending or exempt.
165	func TestActivityGuardEveryViewIsClassified(t *testing.T) {
166		for _, name := range command.AllViewNames() {
167			vt := command.ViewType(name)
168			t.Run(name, func(t *testing.T) {
169				for _, p := range classificationProblems(vt, migratedTables, pendingTables, exemptViews) {
170					t.Errorf("view %q is %s: classify it in activity_guard_test.go", vt, p)
171				}
172			})
173		}
174	}
