176	// The logic itself, on a fictitious view that is partly migrated.
177	func TestActivityGuardClassificationLogic(t *testing.T) {
178		const v command.ViewType = "fiction"
179		pending := []pendingTable{{"fiction/b", v, "A-99"}}
180		tests := []struct {
181			name     string
182			migrated map[command.ViewType][]string
183			pending  []pendingTable
184			exempt   map[command.ViewType]string
185			problems int
186			stale    []string
187			reported []string
188		}{
189			{"partly migrated is fine", map[command.ViewType][]string{v: {"fiction/a"}}, pending, nil, 0, nil, []string{"fiction/a"}},
190			{"unclassified fails", nil, nil, nil, 1, nil, nil},
191			{"same table both ways fails", map[command.ViewType][]string{v: {"fiction/b"}}, pending, nil, 1, []string{"fiction/b"}, []string{"fiction/b"}},
192			{"exempt and pending fails", nil, pending, map[command.ViewType]string{v: "why"}, 1, nil, nil},
193			{"pending table not reported is not stale", map[command.ViewType][]string{v: {"fiction/a"}}, pending, nil, 0, nil, []string{"fiction/a"}},
194		}
195		for _, tt := range tests {
196			t.Run(tt.name, func(t *testing.T) {
197				if got := classificationProblems(v, tt.migrated, tt.pending, tt.exempt); len(got) != tt.problems {
198					t.Errorf("problems = %v, want %d", got, tt.problems)
199				}
200				if got := staleExceptions(v, tt.reported, tt.pending); !equalStrings(got, tt.stale) {
201					t.Errorf("stale = %v, want %v", got, tt.stale)
202				}
203			})
204		}
205	}
206	
207	func equalStrings(a, b []string) bool {
208		if len(a) != len(b) {
209			return false
210		}
211		for i := range a {
212			if a[i] != b[i] {
213				return false
214			}
215		}
216		return true
217	}
