219	// Criteria 1, 4 and the help half of 5, at runtime, on the views the router builds.
220	func TestActivityGuardMigratedViews(t *testing.T) {
221		legendTitle := indicator.Legend().Title
222		for vt, want := range migratedTables {
223			t.Run(string(vt), func(t *testing.T) {
224				m := builtView(t, vt)
225				av, ok := m.(activityView)
226				if !ok {
227					t.Fatalf("view %q is migrated but does not expose ActivityTables()", vt)
228				}
229				tables := av.ActivityTables()
230				for _, name := range want {
231					tb, ok := tables[name]
232					if !ok {
233						t.Errorf("view %q: table %q is migrated but ActivityTables() does not report it (reported: %v)", vt, name, sortedKeys(tables))
234						continue
235					}
236					checkColumnZero(t, vt, name, tb.Shapes())
237					// Criterion 4, Rule 116: the rendered extent, never the sum of columns.
238					if got, want := tb.RenderedWidth(), 60-2; got != want {
239						t.Errorf("view %q table %q: RenderedWidth() = %d at 60 columns, want %d (Rule 116)", vt, name, got, want)
240					}
241				}
242				for name := range tables {
243					if !contains(want, name) {
244						t.Errorf("view %q reports table %q, which migratedTables does not list", vt, name)
245					}
246				}
247				// Criterion 5, help half: the legend.
248				hp, ok := m.(help.Provider)
249				if !ok {
250					t.Fatalf("view %q has no help", vt)
251				}
252				found := false
253				for _, s := range hp.GetHelpContent().Sections {
254					found = found || s.Title == legendTitle
255				}
256				if !found {
257					t.Errorf("view %q: help has no %q section (indicator.Legend)", vt, legendTitle)
258				}
259			})
260		}
261	}
