263	// Criterion 6, other direction: a view that reports a table still listed as
264	// pending has migrated it; the exception must go. An exempt view must report
265	// none at all.
266	func TestActivityGuardNoStaleException(t *testing.T) {
267		for _, name := range command.AllViewNames() {
268			vt := command.ViewType(name)
269			_, isExempt := exemptViews[vt]
270			if !isExempt && len(pendingViews()[vt]) == 0 {
271				continue
272			}
273			t.Run(name, func(t *testing.T) {
274				av, ok := builtView(t, vt).(activityView)
275				if !ok {
276					return
277				}
278				if isExempt {
279					t.Errorf("view %q exposes ActivityTables() but is exempt: move it out of exemptViews", vt)
280				}
281				reported := sortedKeys(av.ActivityTables())
282				if stale := staleExceptions(vt, reported, pendingTables); len(stale) > 0 {
283					t.Errorf("view %q reports %v, still listed as pending: remove the exception", vt, stale)
284				}
285			})
286		}
287	}
