289	func checkColumnZero(t *testing.T, vt command.ViewType, table string, shapes []datatable.ColumnShape) {
290		t.Helper()
291		if len(shapes) == 0 {
292			t.Errorf("view %q table %q: no column reported", vt, table)
293			return
294		}
295		c := shapes[0]
296		var bad []string
297		if !c.Indicator {
298			bad = append(bad, "not an Indicator column")
299		}
300		if c.Title != "" {
301			bad = append(bad, fmt.Sprintf("title %q (want empty)", c.Title))
302		}
303		if c.Sizing != datatable.SizingFixed {
304			bad = append(bad, "not SizingFixed")
305		}
306		if c.MinWidth != datatable.IconColumnWidth {
307			bad = append(bad, fmt.Sprintf("MinWidth %d (want IconColumnWidth)", c.MinWidth))
308		}
309		if c.Less || c.Search {
310			bad = append(bad, "declares Less or Search")
311		}
312		if len(bad) > 0 {
313			t.Errorf("view %q table %q: column 0 is wrong: %s (A-16 criterion 1)", vt, table, strings.Join(bad, "; "))
314		}
315	}
