356	// sourceDeclarationProblems says what is wrong with the link between migrated
357	// views and the sources scanned for them, empty when it is fine. files are the
358	// paths relative to internal/ of every non-test source file.
359	func sourceDeclarationProblems(migrated map[command.ViewType][]string, sources map[command.ViewType][]string, files []string) []string {
360		var problems []string
361		for vt := range migrated {
362			if len(sources[vt]) == 0 {
363				problems = append(problems, fmt.Sprintf("view %q is migrated but declares no source to scan in migratedSources", vt))
364			}
365		}
366		for vt, prefixes := range sources {
367			if len(migrated[vt]) == 0 {
368				problems = append(problems, fmt.Sprintf("view %q has sources in migratedSources but is not migrated (migratedTables)", vt))
369			}
370			for _, p := range prefixes {
371				if !anyHasPrefix(files, p) {
372					problems = append(problems, fmt.Sprintf("view %q: source prefix %q matches no file", vt, p))
373				}
374			}
375		}
376		sort.Strings(problems)
377		return problems
378	}
379	
380	func anyHasPrefix(files []string, prefix string) bool {
381		for _, f := range files {
382			if prefix != "" && strings.HasPrefix(f, prefix) {
383				return true
384			}
385		}
386		return false
387	}
