449	// finding is one retired mechanism found in a source file.
450	type finding struct {
451		Pos  token.Position // file:line:column
452		What string
453	}
454	
455	// bubbleTeaName returns the local name file gives the bubbletea import: its
456	// alias, "." for a dot import, "tea" when unnamed, or "" when the file does not
457	// import it (or blank-imports it). A different package that happens to be
458	// called tea is therefore not mistaken for it.
459	func bubbleTeaName(file *ast.File) string {
460		for _, imp := range file.Imports {
461			path, err := strconv.Unquote(imp.Path.Value)
462			if err != nil || path != "github.com/charmbracelet/bubbletea" {
463				continue
464			}
465			switch {
466			case imp.Name == nil:
467				return "tea"
468			case imp.Name.Name == "_":
469				return ""
470			default:
471				return imp.Name.Name
472			}
473		}
474		return ""
475	}
476	
477	// retiredMechanisms reports, in a migrated view's file, every retired
478	// mechanism: AdvanceSpinner, a StatusColumn: key, a frame field, an activity
479	// glyph literal, and any reference to bubbletea's Tick / Every (under whatever name the file
480	// imports it) outside declaredViewTicks.
481	// rel is the file's path relative to internal/; it is the key of a declared tick.
482	// RenderedFrame (a method of the viewport frame) is allowed.
483	func retiredMechanisms(fset *token.FileSet, file *ast.File, rel string) []finding {
484		var out []finding
485		report := func(pos token.Pos, what string) {
486			out = append(out, finding{Pos: fset.Position(pos), What: what})
487		}
488		tea := bubbleTeaName(file)
489		selectors := map[*ast.Ident]bool{} // identifiers seen as the Sel of a selector
490		// reportTick flags any reference to bubbletea's Tick / Every, called or not
491		// (`var tick = tea.Tick` is as much a tick as `tea.Tick(...)`), unless the
492		// enclosing "<file>:<function>" is declared.
493		reportTick := func(pos token.Pos, fn, name string) {
494			if name != "Tick" && name != "Every" {
495				return
496			}
497			if _, declared := declaredViewTicks[rel+":"+fn]; !declared {
498				report(pos, "reference to bubbletea's "+name+" (a view's rows are animated by the router's tick)")
499			}
500		}
501		isFrame := func(name string) bool {
502			return name == "Frame" || name == "frame" || name == "SpinnerFrame"
503		}
504		visit := func(fn string) func(ast.Node) bool {
505			return func(n ast.Node) bool {
506				switch x := n.(type) {
507				case *ast.CallExpr:
508					sel, ok := x.Fun.(*ast.SelectorExpr)
