124	// classificationProblems says what is wrong with the classification of one
125	// view, empty when it is fine. It works per table: a view may be migrated for
126	// some tables and pending for others (A-09a/A-09a2/A-09b, A-10a/A-10b) as long as the
127	// two sets are disjoint; an exempt view is neither migrated nor pending.
128	func classificationProblems(vt command.ViewType, migrated map[command.ViewType][]string, pending []pendingTable, exempt map[command.ViewType]string) []string {
129		var problems []string
130		mig := migrated[vt]
131		var pend []string
132		for _, p := range pending {
133			if p.View == vt {
134				pend = append(pend, p.Table)
135			}
136		}
137		_, isExempt := exempt[vt]
138		switch {
139		case len(mig) == 0 && len(pend) == 0 && !isExempt:
140			problems = append(problems, "neither migrated, pending (with its story) nor exempt (with its reason)")
141		case isExempt && (len(mig) > 0 || len(pend) > 0):
142			problems = append(problems, "exempt and also migrated or pending")
143		}
144		for _, name := range pend {
145			if contains(mig, name) {
146				problems = append(problems, fmt.Sprintf("table %q is both migrated and pending", name))
147			}
148		}
149		return problems
150	}
