455	// bubbleTeaName returns the local name file gives the bubbletea import: its
456	// alias, "." for a dot import, "tea" when unnamed, or "" when the file does not
457	// import it (or blank-imports it). A different package that happens to be
458	// called tea is therefore not mistaken for it.
459	func bubbleTeaName(file *ast.File) string {
460		for _, imp := range file.Imports {
461			path, err := strconv.Unquote(imp.Path.Value)
462			if err != nil || path != "github.com/charmbracelet/bubbletea" {
463				continue
464			}
465			switch {
466			case imp.Name == nil:
467				return "tea"
468			case imp.Name.Name == "_":
469				return ""
470			default:
471				return imp.Name.Name
472			}
473		}
474		return ""
475	}
