113	type rowChain struct{ Story, What string }
114	
115	// declaredRowChains are the row-animation chains that still live outside the
116	// router (DEVDESK-139, Q2 = A). The list may only shrink: each entry names the
117	// story that removes it, and a stale entry fails the tests below.
118	var declaredRowChains = map[string]rowChain{}
