124	// chainProblems says what is wrong with the declared chains, in file order:
125	// no story, or a story whose tables have all left pendingTables (the chain
126	// should have gone with the migration).
127	func chainProblems(chains map[string]rowChain, pending []pendingTable) []string {
128		var problems []string
129		files := make([]string, 0, len(chains))
130		for f := range chains {
131			files = append(files, f)
132		}
133		sort.Strings(files)
134		for _, f := range files {
135			c := chains[f]
136			if c.Story == "" || c.What == "" {
137				problems = append(problems, f+": declared row animation chain names no story or no description")
138				continue
139			}
140			still := false
141			for _, p := range pending {
142				still = still || p.Story == c.Story
143			}
144			if !still {
145				problems = append(problems, f+": declared for story "+c.Story+", which has no table left in pendingTables: remove the chain ("+c.What+")")
146			}
147		}
148		return problems
149	}
