	}
}

// A table drawn in the same frame the action began has no tick behind it yet.
func TestThereIsAFrameBeforeTheFirstTick(t *testing.T) {
	m := busyTable(t)
	m.MarkBusy("web", "Stopping web")

	if m.spinnerFrame == "" {
